(function() {
  const RANDOM_ID_RE = /^(css-[a-z0-9]+|jss\d+|_[a-zA-Z0-9]{5,}|radix-|headlessui-|makeStyles-\w+|Component_\w+|sc-\w+|styled-\w+|emotion-\w+)/;
