    if (hideStyleEl) return hideStyleEl;
    hideStyleEl = document.createElement('style');
    hideStyleEl.id = 'nor1c-eh-rules';
    (document.head || document.documentElement).appendChild(hideStyleEl);
    return hideStyleEl;
  }

