  6	  const privateSuffixes = new Set(['appspot.com', 'blogspot.com', 'github.io', 'gitlab.io', 'herokuapp.com', 'netlify.app', 'pages.dev', 'vercel.app', 'web.app']);
  7	  const suffix = parts.slice(-2).join('.');
  8	  if (privateSuffixes.has(suffix)) return parts.slice(-3).join('.');
  9	  const commonSecondLevelDomains = new Set(['ac', 'co', 'com', 'edu', 'gov', 'net', 'org']);
 10	  const countryCode = parts[parts.length - 1].length === 2;
 11	  const secondLevel = parts[parts.length - 2];
 12	  const labelCount = countryCode && commonSecondLevelDomains.has(secondLevel) ? 3 : 2;
 13	  return parts.slice(-labelCount).join('.');
